(window.__qhadithX=window.__qhadithX||{})[77]={"1":[{"c":"Sunan Abu Dawud","r":"Hadith 1401","u":"https://quranx.com/Hadith/AbuDawud/DarusSalam/Hadith-1401","x":"Narrated Amr ibn al-'As:\n\nThe Prophet (ﷺ) taught me fifteen prostrations while reciting the Qur'an, including three in al-Mufassal and two in Surah al-Hajj. Abu Dawud said: Abu al-Darda' has reported eleven prostrations from the Prophet (ﷺ), but chain of this tradition is weak.","ar":"حَدَّثَنَا مُحَمَّدُ بْنُ عَبْدِ الرَّحِيمِ بْنِ الْبَرْقِيِّ، حَدَّثَنَا ابْنُ أَبِي مَرْيَمَ، أَخْبَرَنَا نَافِعُ بْنُ يَزِيدَ، عَنِ الْحَارِثِ بْنِ سَعِيدٍ الْعُتَقِيِّ، عَنْ عَبْدِ اللَّهِ بْنِ مُنَيْنٍ، - مِنْ بَنِي عَبْدِ كُلاَلٍ - عَنْ عَمْرِو بْنِ الْعَاصِ، أَنَّ رَسُولَ اللَّهِ صلى الله عليه وسلم أَقْرَأَهُ خَمْسَ عَشْرَةَ سَجْدَةً فِي الْقُرْآنِ مِنْهَا ثَلاَثٌ فِي الْمُفَصَّلِ وَفِي سُورَةِ الْحَجِّ سَجْدَتَانِ ‏.‏ قَالَ أَبُو دَاوُدَ رُوِيَ عَنْ أَبِي الدَّرْدَاءِ عَنِ النَّبِيِّ صلى الله عليه وسلم إِحْدَى عَشْرَةَ سَجْدَةً وَإِسْنَادُهُ وَاهٍ ‏.‏","v":[]},{"c":"Sahih Bukhari","r":"Hadith 1830","u":"https://quranx.com/Hadith/Bukhari/DarusSalam/Hadith-1830","x":"Narrated `Abdullah:\n\nWhile we were in the company of the Prophet (ﷺ) in a cave at Mina, when Surat-wal-Mursalat were revealed and he recited it and I heard it (directly) from his mouth as soon as he recited its revelation. Suddenly a snake sprang at us and the Prophet (ﷺ) said (ordered us): \"Kill it.\" We ran to kill it but it escaped quickly. The Prophet (ﷺ) said, \"It has escaped your evil and you too have escaped its evil.\"","ar":"حَدَّثَنَا عُمَرُ بْنُ حَفْصِ بْنِ غِيَاثٍ، حَدَّثَنَا أَبِي، حَدَّثَنَا الأَعْمَشُ، قَالَ حَدَّثَنِي إِبْرَاهِيمُ، عَنِ الأَسْوَدِ، عَنْ عَبْدِ اللَّهِ ـ رضى الله عنه ـ قَالَ بَيْنَمَا نَحْنُ مَعَ النَّبِيِّ صلى الله عليه وسلم فِي غَارٍ بِمِنًى، إِذْ نَزَلَ عَلَيْهِ ‏{‏وَالْمُرْسَلاَتِ‏}‏ وَإِنَّهُ لَيَتْلُوهَا، وَإِنِّي لأَتَلَقَّاهَا مِنْ فِيهِ، وَإِنَّ فَاهُ لَرَطْبٌ بِهَا، إِذْ وَثَبَتْ عَلَيْنَا حَيَّةٌ فَقَالَ النَّبِيُّ صلى الله عليه وسلم ‏\"‏ اقْتُلُوهَا ‏\"‏‏.‏ فَابْتَدَرْنَاهَا، فَذَهَبَتْ، فَقَالَ النَّبِيُّ صلى الله عليه وسلم ‏\"‏ وُقِيَتْ شَرَّكُمْ كَمَا وُقِيتُمْ شَرَّهَا ‏\"‏‏.‏","v":[]}],"32":[{"c":"Sahih Bukhari","r":"Hadith 4933","u":"https://quranx.com/Hadith/Bukhari/DarusSalam/Hadith-4933","x":"Narrated Ibn 'Abbas:\n\n(regarding) the explanation of \"... It throws sparks as Al-Qasr...\" (V. 77:32): We used to collect logs of wood, three cubits long or longer, to store for heating purposes in winter, and we used to call it Al- Qasr, it also means a castle or a fort. \"As if they were Jimalatun Sufr (yellow camels or bundles of ropes)\" (V.77:33): means the ropes of a ship which are made in bundles till it become as wide as men's waists.","ar":"حَدَّثَنَا عَمْرُو بْنُ عَلِيٍّ، حَدَّثَنَا يَحْيَى، أَخْبَرَنَا سُفْيَانُ، حَدَّثَنِي عَبْدُ الرَّحْمَنِ بْنُ عَابِسٍ، سَمِعْتُ ابْنَ عَبَّاسٍ ـ رضى الله عنهما ـ ‏{‏تَرْمِي بِشَرَرٍ‏}‏ كُنَّا نَعْمِدُ إِلَى الْخَشَبَةِ ثَلاَثَةَ أَذْرُعٍ وَفَوْقَ ذَلِكَ، فَنَرْفَعُهُ لِلشِّتَاءِ فَنُسَمِّيهِ الْقَصَرَ‏.‏ ‏{‏كَأَنَّهُ جِمَالاَتٌ صُفْرٌ‏}‏ حِبَالُ السُّفْنِ تُجْمَعُ حَتَّى تَكُونَ كَأَوْسَاطِ الرِّجَالِ‏.‏","v":[]}],"33":[{"c":"Sahih Bukhari","r":"Hadith 4933","u":"https://quranx.com/Hadith/Bukhari/DarusSalam/Hadith-4933","x":"Narrated Ibn 'Abbas:\n\n(regarding) the explanation of \"... It throws sparks as Al-Qasr...\" (V. 77:32): We used to collect logs of wood, three cubits long or longer, to store for heating purposes in winter, and we used to call it Al- Qasr, it also means a castle or a fort. \"As if they were Jimalatun Sufr (yellow camels or bundles of ropes)\" (V.77:33): means the ropes of a ship which are made in bundles till it become as wide as men's waists.","ar":"حَدَّثَنَا عَمْرُو بْنُ عَلِيٍّ، حَدَّثَنَا يَحْيَى، أَخْبَرَنَا سُفْيَانُ، حَدَّثَنِي عَبْدُ الرَّحْمَنِ بْنُ عَابِسٍ، سَمِعْتُ ابْنَ عَبَّاسٍ ـ رضى الله عنهما ـ ‏{‏تَرْمِي بِشَرَرٍ‏}‏ كُنَّا نَعْمِدُ إِلَى الْخَشَبَةِ ثَلاَثَةَ أَذْرُعٍ وَفَوْقَ ذَلِكَ، فَنَرْفَعُهُ لِلشِّتَاءِ فَنُسَمِّيهِ الْقَصَرَ‏.‏ ‏{‏كَأَنَّهُ جِمَالاَتٌ صُفْرٌ‏}‏ حِبَالُ السُّفْنِ تُجْمَعُ حَتَّى تَكُونَ كَأَوْسَاطِ الرِّجَالِ‏.‏","v":[]}],"50":[{"c":"Sunan Abu Dawud","r":"Hadith 888","u":"https://quranx.com/Hadith/AbuDawud/DarusSalam/Hadith-888","x":"Narrated Anas ibn Malik:\n\nI did not offer behind anyone after the Messenger of Allah (ﷺ) a prayer like the prayer offered by the Messenger of Allah (ﷺ) than this youth, i.e. Umar ibn AbdulAziz. We estimated reciting glorification ten times in his bowing, and in his prostration ten times. Abu Dawud said: Ahmad b. Salih said: I asked him ('Abd Allah) whether the name Manus is correct of Mabus. He replied: 'Abd al-Razzaq used to say Mabus, but I remember Manus (i.e. the narrator Wahb b. Manus). These are the words of Ibn Rafi'. It has also been narrated by Ahmad from Sa'id b. Jubair on the authority of Anas b. Malik.","ar":"حَدَّثَنَا أَحْمَدُ بْنُ صَالِحٍ، وَابْنُ، رَافِعٍ قَالاَ حَدَّثَنَا عَبْدُ اللَّهِ بْنُ إِبْرَاهِيمَ بْنِ عُمَرَ بْنِ كَيْسَانَ، حَدَّثَنِي أَبِي، عَنْ وَهْبِ بْنِ مَانُوسٍ، قَالَ سَمِعْتُ سَعِيدَ بْنَ جُبَيْرٍ، يَقُولُ سَمِعْتُ أَنَسَ بْنَ مَالِكٍ، يَقُولُ مَا صَلَّيْتُ وَرَاءَ أَحَدٍ بَعْدَ رَسُولِ اللَّهِ صلى الله عليه وسلم أَشْبَهَ صَلاَةً بِرَسُولِ اللَّهِ صلى الله عليه وسلم مِنْ هَذَا الْفَتَى يَعْنِي عُمَرَ بْنَ عَبْدِ الْعَزِيزِ ‏.‏ قَالَ فَحَزَرْنَا فِي رُكُوعِهِ عَشْرَ تَسْبِيحَاتٍ وَفِي سُجُودِهِ عَشْرَ تَسْبِيحَاتٍ ‏.‏ قَالَ أَبُو دَاوُدَ قَالَ أَحْمَدُ بْنُ صَالِحٍ قُلْتُ لَهُ مَانُوسٌ أَوْ مَابُوسٌ قَالَ أَمَّا عَبْدُ الرَّزَّاقِ فَيَقُولُ مَابُوسٌ وَأَمَّا حِفْظِي فَمَانُوسٌ وَهَذَا لَفْظُ ابْنِ رَافِعٍ ‏.‏ قَالَ أَحْمَدُ عَنْ سَعِيدِ بْنِ جُبَيْرٍ عَنْ أَنَسِ بْنِ مَالِكٍ ‏.‏","v":[]}]};